import { useState, useCallback, useEffect, memo } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { Bookmark, BookmarkCheck, Trash2, Film, Tv, Star, ArrowLeft, Grid, List, ChevronDown } from 'lucide-react';
import MediaCard from '../components/MediaCard';
import { img } from '../lib/tmdb';
import { useSettings } from '../contexts/SettingsContext';
import { useToast } from '../contexts/ToastContext';

interface WatchlistItem {
  id: number;
  title?: string;
  name?: string;
  poster_path: string | null;
  media_type?: 'movie' | 'tv';
  overview?: string;
  vote_average?: number;
  release_date?: string;
  first_air_date?: string;
}

function WatchlistPageInner() {
  const navigate = useNavigate();
  const { settings, updateSetting } = useSettings();
  const { addToast } = useToast();
  const [items, setItems] = useState<WatchlistItem[]>([]);
  const [viewMode, setViewMode] = useState<'grid' | 'list'>(() => {
    try {
      const saved = localStorage.getItem('stinkflix-viewMode');
      if (saved === 'list' || saved === 'grid') return saved;
    } catch { /* storage unavailable */ }
    return settings.listView ? 'list' : 'grid';
  });
  const [confirmRemove, setConfirmRemove] = useState<number | null>(null);

  // Load watchlist from localStorage
  const loadWatchlist = useCallback(() => {
    try {
      const ids = localStorage.getItem('watchlist-ids');
      const idList = ids ? JSON.parse(ids) : [];
      
      const loaded = idList
        .map((id: number) => {
          const item = localStorage.getItem(`watchlist-item-${id}`);
          return item ? JSON.parse(item) : null;
        })
        .filter(Boolean);

      setItems(loaded);
    } catch (error) {
      console.error('Failed to load watchlist:', error);
      addToast('Failed to load watchlist', 'error');
    }
  }, [addToast]);

  // Load on mount
  useEffect(() => {
    loadWatchlist();
  }, [loadWatchlist]);

  const removeFromWatchlist = useCallback((id: number) => {
    const newItems = items.filter(item => item.id !== id);
    setItems(newItems);
    
    const idList = localStorage.getItem('watchlist-ids');
    const parsed = idList ? JSON.parse(idList) : [];
    const newList = parsed.filter((i: number) => i !== id);
    localStorage.setItem('watchlist-ids', JSON.stringify(newList));
    localStorage.removeItem(`watchlist-item-${id}`);

    setConfirmRemove(null);
    addToast('Removed from watchlist', 'info');
  }, [items, addToast]);

  const clearAll = useCallback(() => {
    const newItems = [];
    setItems([]);
    localStorage.removeItem('watchlist-ids');
    items.forEach(item => {
      localStorage.removeItem(`watchlist-item-${item.id}`);
    });
    addToast('Watchlist cleared', 'info');
  }, [items, addToast]);

  const mediaType = (items[0]?.media_type || 'movie') as 'movie' | 'tv';

  return (
    <div className="min-h-screen bg-[#0a0a0f] pt-16">
      {/* Header */}
      <div className="sticky top-16 z-40 bg-[#0a0a0f]/95 backdrop-blur-xl border-b border-white/5">
        <div className="max-w-full lg:max-w-[1600px] xl:max-w-[2000px] 2xl:max-w-[2560px] mx-auto px-4 sm:px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <button
                onClick={() => navigate(-1)}
                className="p-2 text-white/50 hover:text-white hover:bg-white/10 rounded-lg transition-all"
              >
                <ArrowLeft size={20} />
              </button>
              <div>
                <h1 className="text-xl sm:text-2xl font-bold text-white flex items-center gap-2">
                  <BookmarkCheck size={22} className="text-emerald-400" />
                  Watchlist
                </h1>
                <p className="text-white/40 text-sm">{items.length} item{items.length !== 1 ? 's' : ''}</p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              {items.length > 0 && (
                <>
                  <button
                    onClick={clearAll}
                    className="flex items-center gap-2 px-3 py-2 bg-red-500/10 hover:bg-red-500/20 text-red-400 rounded-lg transition-all text-sm"
                  >
                    <Trash2 size={14} />
                    <span className="hidden sm:inline">Clear All</span>
                  </button>
                  <div className="flex items-center bg-white/5 border border-white/10 rounded-lg overflow-hidden">
                    <button
                      onClick={() => setViewMode('grid')}
                      className={`p-2 transition-all ${
                        viewMode === 'grid' ? 'bg-emerald-500/20 text-emerald-400' : 'text-white/50 hover:text-white'
                      }`}
                    >
                      <Grid size={16} />
                    </button>
                    <button
                      onClick={() => setViewMode('list')}
                      className={`p-2 transition-all ${
                        viewMode === 'list' ? 'bg-emerald-500/20 text-emerald-400' : 'text-white/50 hover:text-white'
                      }`}
                    >
                      <List size={16} />
                    </button>
                  </div>
                </>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="max-w-full lg:max-w-[1600px] xl:max-w-[2000px] 2xl:max-w-[2560px] mx-auto px-4 sm:px-6 py-6">
        {items.length > 0 ? (
          <div className={`grid gap-4 ${
            viewMode === 'grid'
              ? 'grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 2xl:grid-cols-8'
              : 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4'
          }`}>
            {items.map((item, index) => {
              const type = (item.media_type || 'movie') as string;
              const title = item.title || item.name || 'Unknown';
              const year = (item.release_date || item.first_air_date || '').slice(0, 4);
              const poster = item.poster_path ? img(item.poster_path, 'w342') : null;

              return (
                <div key={item.id} className="relative group">
                  <MediaCard
                    item={{
                      id: item.id,
                      title,
                      poster_path: item.poster_path ?? null,
                      backdrop_path: null,
                      overview: item.overview || '',
                      vote_average: item.vote_average ?? 0,
                      media_type: item.media_type as 'movie' | 'tv',
                    }}
                    mediaType={item.media_type as 'movie' | 'tv'}
                    index={index}
                    viewMode={viewMode}
                  />
                  <button
                    onClick={() => setConfirmRemove(item.id)}
                    className="absolute top-2 right-2 p-1.5 bg-red-500/80 hover:bg-red-500 text-white rounded-lg transition-all opacity-0 group-hover:opacity-100 z-10"
                    aria-label="Remove from watchlist"
                  >
                    <Trash2 size={14} />
                  </button>

                  {confirmRemove === item.id && (
                    <div className="absolute inset-0 bg-black/80 rounded-xl flex items-center justify-center z-20">
                      <div className="text-center p-3">
                        <p className="text-white text-xs font-medium mb-2">Remove from watchlist?</p>
                        <div className="flex gap-1">
                          <button
                            onClick={() => removeFromWatchlist(item.id)}
                            className="px-2 py-1 bg-red-500 text-white rounded text-[10px] font-medium"
                          >
                            Remove
                          </button>
                          <button
                            onClick={() => setConfirmRemove(null)}
                            className="px-2 py-1 bg-white/20 text-white rounded text-[10px] font-medium"
                          >
                            Cancel
                          </button>
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        ) : (
          <div className="text-center py-24">
            <Bookmark size={56} className="mx-auto text-white/10 mb-5" />
            <p className="text-white/30 text-lg font-medium">Your watchlist is empty</p>
            <p className="text-white/20 text-sm mt-2">Add movies and TV shows to keep track of them</p>
            <button
              onClick={() => navigate('/')}
              className="mt-6 px-6 py-2.5 bg-emerald-500 hover:bg-emerald-400 text-white rounded-xl transition-all text-sm font-semibold"
            >
              Browse Content
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

export default memo(WatchlistPageInner);